def td_taper(out, start, end, beta=8, side='left'):
    n = len(out)
    window = kaiser(n, beta=beta)
    if side == 'left':
        window[:int(start * out.fs)] = 0
        window[int(end * out.fs):] = 1
    elif side == 'right':
        window[:int(start * out.fs)] = 1
        window[int(end * out.fs):] = 0
    else:
        raise ValueError("Invalid side: must be 'left' or 'right'.")
    return out * window

