def remove(self, key, column_path, timestamp, consistency_level):
    """
    Remove data from the row specified by key at the granularity specified by column_path, and the given timestamp. Note
    that all the values in column_path besides column_path.column_family are truly optional: you can remove the entire
    row by just specifying the ColumnFamily, or you can remove a SuperColumn or a single Column by specifying those levels too.

    Parameters:
     - key
     - column_path
     - timestamp
     - consistency_level
    """
    if not column_path.column_family:
        raise ValueError("Column family is required")
    if not key:
        raise ValueError("Key is required")
    if not timestamp:
        raise ValueError("Timestamp is required")
    if not consistency_level:
        raise ValueError("Consistency level is required")
    if column_path.super_column and column_path.column:
        self.remove_column(key, column_path, timestamp, consistency_level)
    elif column_path.super_column:
        self.remove_super_column(key, column_path, timestamp, consistency_level)
    else:
        self.remove_column_family(key, column_path, timestamp, consistency_level)

