async def send_message(
        self, request: str, response_expected: bool, **kwargs: Any
    ) -> Response:
        """
        Transport the message to the server and return the response.

        Args:
            request: The JSON-RPC request string.
            response_expected: Whether the request expects a response.

        Returns:
            A Response object.
        """
        if not self.connected:
            raise ConnectionError("Not connected to the server")
        if not isinstance(request, str):
            raise ValueError("Request must be a string")
        if not isinstance(response_expected, bool):
            raise ValueError("response_expected must be a boolean")
        if not self.loop:
            self.loop = asyncio.get_event_loop()
        if not self.writer:
            self.writer = await self.loop.create_writer(self.reader, self.writer, self.host, self.port)
        if not self.reader:
            self.reader = await self.loop.create_reader(self.reader, self.writer, self.host, self.port)
        self.writer.write(request.encode())
        if response_expected:
            response = await self.reader.read()
            return Response(response)
        else:
            return Response(None)

