def enumerations(
            self,
            name=None,
            function=None,
            header_dir=None,
            header_file=None,
            recursive=None,
            allow_empty=None):
        """returns a set of enumeration declarations, that are matched
        defined criteria"""
        enumerations = set()
        for declaration in self.declarations:
            if isinstance(declaration, c_enum):
                if name is not None and declaration.name!= name:
                    continue
                if function is not None and declaration.function!= function:
                    continue
                if header_dir is not None and declaration.header_dir!= header_dir:
                    continue
                if header_file is not None and declaration.header_file!= header_file:
                    continue
                if recursive is not None and declaration.recursive!= recursive:
                    continue
                if allow_empty is not None and declaration.allow_empty!= allow_empty:
                    continue
                enumerations.add(declaration)
        return enumerations

