def create_disk(name, size):
    size_pattern = re.compile(r"^(\d+)(?:([KMGTP])B?)?$")
    match = size_pattern.match(size)
    if not match:
        raise ValueError("Invalid size format")
    size_value, size_unit = match.groups()
    size_value = int(size_value)
    if size_unit:
        size_unit = size_unit.upper()
        size_multipliers = {"K": 1024, "M": 1024**2, "G": 1024**3, "T": 1024**4}
        size_value *= size_multipliers[size_unit]
    with open(name, "wb") as disk_file:
        disk_file.write(b"\0" * size_value)

