def trim_shared_flanking_strings(ref, alt):
    """
    Given two nucleotide or amino acid strings, identify
    if they have a common prefix, a common suffix, and return
    their unique components along with the prefix and suffix.

    For example, if the input ref = "SYFFQGR" and alt = "SYMLLFIFQGR"
    then the result will be:
        ("F", "MLLFI", "SY", "FQGR")
    """
    prefix = ''
    suffix = ''
    for i in range(min(len(ref), len(alt))):
        if ref[i] == alt[i]:
            prefix += ref[i]
        else:
            break
    for i in range(1, min(len(ref), len(alt)) + 1):
        if ref[-i] == alt[-i]:
            suffix = ref[-i] + suffix
        else:
            break
    unique_ref = ref.replace(prefix, '').replace(suffix, '')
    unique_alt = alt.replace(prefix, '').replace(suffix, '')
    return (unique_ref, unique_alt, prefix, suffix)

