def decorate(fn):
    assert asyncio.iscoroutinefunction(fn), "Place @timesout before @coroutine"

    @wraps(fn)
    @asyncio.coroutine
    def wrapper(*args, timeout=deftimeout, **kws):
        loop = kws.get('loop')
        fut = fn(*args, **kws)
        if timeout is None:
            yield from fut
        else:
            yield from asyncio.wait_for(fut, timeout=timeout, loop=loop)
    return wrapper
