def fragment(pkt, fragsize=1480):
    """Fragment a big IP datagram"""
    if len(pkt) <= fragsize:
        return [pkt]
    nfragments = (len(pkt) + fragsize - 1) // fragsize
    fragments = []
    for i in range(nfragments):
        fragment = pkt[i*fragsize:(i+1)*fragsize]
        fragments.append(fragment)
    return fragments

