def find_most_distant(self, input_sample, num_samples,
                          num_params, k_choices, num_groups=None):
    if num_groups is None:
        num_groups = num_samples
    groups = np.array_split(input_sample, num_groups)
    distances = np.zeros(num_groups)
    for i, group in enumerate(groups):
        distances[i] = np.linalg.norm(group - input_sample[i])
    sorted_indices = np.argsort(distances)[-k_choices:]
    return input_sample[sorted_indices]

