def run_get_clusters_from_file(self, clusters_infile, all_ref_seqs, rename_dict=None):
        """Instead of running cdhit, gets the clusters info from the input file."""
        clusters = {}
        with open(clusters_infile, 'r') as infile:
            for line in infile:
                line = line.strip()
                if line.startswith('>'):
                    seq_id = line[1:].split()[0]
                    if rename_dict and seq_id in rename_dict:
                        seq_id = rename_dict[seq_id]
                    cluster_id = line.split('... ')[1]
                    if cluster_id not in clusters:
                        clusters[cluster_id] = []
                    clusters[cluster_id].append(seq_id)
        return clusters

