def unmarshal_json(obj, cls, allow_extra_keys=True, ctor=None):
    if not hasattr(cls, '__init__'):
        raise ValueError(f'Class {cls.__name__} does not have an __init__ method')
    if ctor is not None:
        if not callable(ctor):
            raise ValueError(f'ctor {ctor} is not callable')
