        r, g, b = self.rgb
        r, g, b = r / 255, g / 255, b / 255
        max_value = max(r, g, b)
        min_value = min(r, g, b)
        brightness = max_value
        if max_value == 0:
            saturation = 0
        else:
            saturation = (max_value - min_value) / max_value
        if max_value == min_value:
            hue = 0
        elif max_value == r:
            hue = (g - b) / (max_value - min_value) % 6
        elif max_value == g:
            hue = (b - r) / (max_value - min_value) + 2
        elif max_value == b:
            hue = (r - g) / (max_value - min_value) + 4
