def __eval_validator_check(self, check_item, resp_obj):
        """ evaluate check item in validator.

        Args:
            check_item: check_item should only be the following 5 formats:
                1, variable reference, e.g. $token
                2, function reference, e.g. ${is_status_code_200($status_code)}
                3, dict or list, maybe containing variable/function reference, e.g. {"var": "$abc"}
                4, string joined by delimiter. e.g. "status_code", "headers.content-type"
                5, regex string, e.g. "LB[\d]*(.*)RB[\d]*"

            resp_obj: response object

        """
        if isinstance(check_item, str):
            if check_item.startswith('$'):
                var_name = check_item[1:]
                return getattr(resp_obj, var_name)
            elif check_item.startswith('${') and check_item.endswith('}'):
                func_name, arg = check_item[2:-1].split('(')
                func = getattr(resp_obj, func_name)
                return func(arg)
            elif '.' in check_item:
                parts = check_item.split('.')
                return self.__eval_validator_check(parts[0], resp_obj)[parts[1]]
            else:
                return check_item
        elif isinstance(check_item, (list, tuple)):
            return [self.__eval_validator_check(item, resp_obj) for item in check_item]
        elif isinstance(check_item, dict):
            return {key: self.__eval_validator_check(value, resp_obj) for key, value in check_item.items()}
        elif isinstance(check_item, int):
            return check_item
        else:
            raise ValueError(f"Unsupported check item type: {type(check_item)}")

