def removeSinglePixels(img):
    """
    img - boolean array
    remove all pixels that have no neighbour
    """
    m, n = len(img), len(img[0])
    for i in range(m):
        for j in range(n):
            if not img[i][j]:
                continue
            neighbors = 0
            for x in range(max(0, i-1), min(m, i+2)):
                for y in range(max(0, j-1), min(n, j+2)):
                    if img[x][y]:
                        neighbors += 1
            if neighbors == 1:
                img[i][j] = False

