def pick_unused_port(pid=None, portserver_address=None):
    if pid is None:
        pid = os.getpid()
    if portserver_address is None:
        portserver_address = os.environ.get("PORTSERVER_ADDRESS")
    if portserver_address is None:
        raise ValueError("No port server address provided or found in environment")
    with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as sock:
        sock.connect(portserver_address)
        sock.sendall(f"{pid}\n".encode("utf-8"))
        port = int(sock.recv(1024).decode("utf-8"))
    sock = socket.socket()
    try:
        sock.bind(("", port))
    except socket.error:
        raise ValueError("No free port could be found")
    sock.close()

    return port

