    pt1_p, pt2_p - endpoints of first line segment
    pt1_q, pt2_q - endpoints of second line segment
    """
    def cross_product(v1, v2):
        return v1[0] * v2[1] - v1[1] * v2[0]

    def is_between(x, a, b):
        return (a <= x <= b) or (b <= x <= a)

