        v3 = (pt1[0] - pt3[0], pt1[1] - pt3[1])
        v4 = (pt2[0] - pt4[0], pt2[1] - pt4[1])
        if cross_product(v1, v3) * cross_product(v1, v4) > 0:
            return False
        if cross_product(v2, v3) * cross_product(v2, v4) > 0:
            return False
        if not is_between(pt1[0], pt3[0], pt4[0]) or not is_between(pt1[1], pt3[1], pt4[1]):
            return False
        if not is_between(pt2[0], pt3[0], pt4[0]) or not is_between(pt2[1], pt3[1], pt4[1]):
