def get_frip(self, sample):
        """
        Calculates the fraction of reads in peaks for a given sample.

        :param pipelines.Sample sample: Sample object with "peaks" attribute.
        """
        if not hasattr(sample, "peaks"):
            raise AttributeError("Sample object must have 'peaks' attribute.")
        if not hasattr(sample, "bam"):
            raise AttributeError("Sample object must have 'bam' attribute.")
        num_reads_in_peaks = 0
        num_total_reads = 0
        with pysam.AlignmentFile(sample.bam, "rb") as bam_file:
            for read in bam_file.fetch():
                num_total_reads += 1
                if read.is_unmapped:
                    continue
                for peak in sample.peaks:
                    if peak.chrom == read.reference_name and peak.start <= read.pos <= peak.end:
                        num_reads_in_peaks += 1
                        break
        if num_total_reads == 0:
            return 0.0
        return num_reads_in_peaks / num_total_reads

