def cast(cls, value, cast=str, subcast=None):
        """
        Parse and cast provided value.

        :param value: Stringed value.
        :param cast: Type or callable to cast return value as.
        :param subcast: Subtype or callable to cast return values as (used for
                        nested structures).

        :returns: Value of type `cast`.
        """
        if cast == str:
            return value
        elif cast == int:
            return int(value)
        elif cast == float:
            return float(value)
        elif cast == bool:
            return bool(int(value))
        elif callable(cast):
            return cast(value)
        elif isinstance(cast, type) and issubclass(cast, dict):
            return {k: cast(k, v, subcast) for k, v in value.items()}
        elif isinstance(cast, type) and issubclass(cast, list):
            return [cast(i, subcast) for i in value]
        elif isinstance(cast, type) and issubclass(cast, tuple):
            return tuple(cast(i, subcast) for i in value)
        else:
            raise TypeError("Invalid cast type.")

