def histogram1d(x, bins, range, weights=None):
    bin_width = (range[1] - range[0]) / bins
    bin_indices = np.floor((x - range[0]) / bin_width).astype(int)
    bin_indices = np.clip(bin_indices, 0, bins - 1)
    if weights is None:
        weights = np.ones_like(x)
    array = np.zeros(bins)
    for i, weight in zip(bin_indices, weights):
        array[i] += weight

    return array

