def clustering_coef_wd(W):
    W = np.power(W, 1/3)
    C = np.zeros(W.shape[0])
    for i in range(W.shape[0]):
        neighbors = np.nonzero(W[i])[0]
        if len(neighbors) < 2:
            C[i] = 0
        else:
            numerator = 0
            for j in neighbors:
                numerator += np.sum(W[j, neighbors])
            denominator = len(neighbors) * (len(neighbors) - 1)
            C[i] = numerator / denominator

    return C

