def _init():
    """Try loading each binding in turn

    Please note: the entire Qt module is replaced with this code:
        sys.modules["Qt"] = binding()

    This means no functions or variables can be called after
    this has executed.

    """
    import sys
    import os

    def binding():
        if os.name == 'posix':
            try:
                import PySide2
                return PySide2
            except ImportError:
                import PyQt5
                return PyQt5
        elif os.name == 'nt':
            try:
                import PyQt5
                return PyQt5
            except ImportError:
                import PySide2
                return PySide2
        else:
            raise ImportError("No supported binding found")

    sys.modules["Qt"] = binding()

