def combine_nested_dicts(*nested_dicts, depth=-1, base=None):
    """
    Merge nested-dictionaries.

    :param nested_dicts:
        Nested dictionaries.
    :type nested_dicts: dict

    :param depth:
        Maximum keys depth.
    :type depth: int, optional

    :param base:
        Base dict where combine multiple dicts in one.
    :type base: dict, optional

    :return:
        Combined nested-dictionary.
    :rtype: dict
    """
    if not nested_dicts:
        return base or {}

    def _combine(d1, d2, depth=0):
        for k, v2 in d2.items():
            if k in d1:
                v1 = d1[k]
                if isinstance(v1, dict) and isinstance(v2, dict):
                    if depth < 0 or depth > 1:
                        d1[k] = _combine(v1, v2, depth - 1)
                else:
                    d1[k] = v2
            else:
                d1[k] = v2
        return d1

    return _combine(nested_dicts[0].copy(), combine_nested_dicts(*nested_dicts[1:], depth=depth, base=base))

