def compute_training_sizes(train_perc, class_sizes, stratified=True):
    """Computes the maximum training size that the smallest class can provide """
    if not isinstance(train_perc, float) or not (0 < train_perc < 1):
        raise ValueError("train_perc must be a float between 0 and 1")
    if not isinstance(class_sizes, list) or not all(isinstance(size, int) for size in class_sizes):
        raise ValueError("class_sizes must be a list of integers")
    if not isinstance(stratified, bool):
        raise ValueError("stratified must be a boolean")
    if stratified:
        min_size = min(class_sizes)
        max_size = max(class_sizes)
        max_training_size = min_size * train_perc
        return max_training_size
    else:
        max_size = max(class_sizes)
        max_training_size = max_size * train_perc
        return max_training_size

