def increment(self, method=None, url=None, response=None, error=None, _pool=None, _stacktrace=None):
        """ Return a new Retry object with incremented retry counters.

        :param response: A response object, or None, if the server did not
            return a response.
        :type response: :class:`~urllib3.response.HTTPResponse`
        :param Exception error: An error encountered during the request, or
            None if the response was received successfully.

        :return: A new ``Retry`` object.
        """
        if self.total is not None:
            self.total -= 1

        if response is not None:
            if response.status in self.status_count:
                self.status_count[response.status] += 1
            else:
                self.status_count[response.status] = 1

            if response.reason in self.reason_count:
                self.reason_count[response.reason] += 1
            else:
                self.reason_count[response.reason] = 1
        elif error is not None:
            if isinstance(error, ConnectionError):
                self.connect += 1
            elif isinstance(error, ReadTimeoutError):
                self.read += 1

        return Retry(self.total, self.connect, self.read, self.redirect, self.status_count, self.reason_count, self.redirect_count)

