def getCommon(self, st1, st2):
		"""
		getCommon() returns the length of the longest common substring
		of both arguments, starting at the beginning of both.
		"""
		if not st1 or not st2:
			return 0
		if st1[0] == st2[0]:
			return 1 + self.getCommon(st1[1:], st2[1:])
