        prefixes = []
        node = self.root
        for char in key:
            if char not in node.children:
                return []
            node = node.children[char]
        queue = [(node, key)]
        while queue:
            node, prefix = queue.pop(0)
            if node.is_word:
                prefixes.append(prefix)
            for char, child in node.children.items():
                queue.append((child, prefix + char))

        return prefixes

