def derivative(func, x0, dx=1.0, n=1, args=(), order=3):
    """Reimplementation of SciPy's derivative function, with more cached
    coefficients and without using numpy. If new coefficients not cached are
    needed, they are only calculated once and are remembered.
    """
    if order < n + 1:
        raise ValueError
    if order % 2 == 0:
        raise ValueError
    weights = central_diff_weights(order, n)
    tot = 0.0
    ho = order >> 1
    for k in range(order):
        tot += weights[k]*func(x0 + (k - ho)*dx, *args)
    return tot/product([dx]*n)

mgc_code:
def derivative(func, x0, dx=1.0, n=1, args=(), order=3):
    """Reimplementation of SciPy's derivative function, with more cached
    coefficients and without using numpy. If new coefficients not cached are
    needed, they are only calculated once and are remembered.
    """
    if order not in (2, 3, 4, 5):
        raise ValueError("Order must be 2, 3, 4, or 5.")
    if order == 2:
        coefficients = {
            0: 1,
            1: -2,
            2: 1,
        }
    elif order == 3:
        coefficients = {
            0: -1 / 2,
            1: 0,
            2: 1 / 2,
        }
    elif order == 4:
        coefficients = {
            0: 1 / 12,
            1: -2 / 3,
            2: 0,
            3: 2 / 3,
            4: -1 / 12,
        }
    elif order == 5:
        coefficients = {
            0: -1 / 60,
            1: 3 / 20,
            2: -3 / 4,
            3: 0,
            4: 3 / 4,
            5: -3 / 20,
            6: 1 / 60,
        }
    if n < 0:
        return derivative(lambda x: func(x) ** n, x0, dx, -n, args, order)
    if n == 0:
        return func(x0, *args)
    if n == 1:
        return sum(coefficients[i] * func(x0 + (i - order // 2) * dx, *args) for i in range(order)) / dx
    return derivative(lambda x: func(x, *args), x0, dx, n - 1, (), order)

