def delete(
        collection_name, spec, safe, last_error_args, opts, flags=0, ctx=None):
    """Get a **delete** message.

    `opts` is a CodecOptions. `flags` is a bit vector that may contain
    the SingleRemove flag or not:

    http://docs.mongodb.org/meta-driver/latest/legacy/mongodb-wire-protocol/#op-delete
    """
    message = {
        "delete": collection_name,
        "flags": flags,
        "deletes": [
            {
                "q": spec,
                "limit": 1 if flags & 1 else 0,
            }
        ]
    }
    if safe:
        message["ordered"] = True
        message["getlasterror"] = 1
        message.update(last_error_args)
    if opts:
        message["$db"] = opts.db_name
    return message

