def bin_sparse(M, subsampling_factor=3):
    """Perform the bin_dense procedure for sparse matrices. Remaining rows
    and cols are lumped with the rest at the end.
    """
    if not isinstance(M, np.sparse.spmatrix):
        raise ValueError("Input must be a sparse matrix.")
    if subsampling_factor < 1:
        raise ValueError("Subsampling factor must be at least 1.")
    num_rows, num_cols = M.shape
    num_bins = min(num_rows, num_cols) // subsampling_factor
    bin_sizes = np.zeros(num_bins, dtype=int)
    for i in range(num_rows):
        for j in range(num_cols):
            if M[i, j]!= 0:
                bin_index = min(i, num_bins - 1)
                bin_sizes[bin_index] += 1
    return bin_sizes

