def table_from_gwf(filename, name, columns=None, selection=None):
    """Read a Table from FrEvent structures in a GWF file (or files)

    Parameters
    ----------
    filename : `str`
        path of GWF file to read

    name : `str`
        name associated with the `FrEvent` structures

    columns : `list` of `str`
        list of column names to read

    selection : `str`, `list` of `str`
        one or more column selection strings to apply, e.g. ``'snr>6'``
    """
    if not isinstance(filename, str):
        raise TypeError("filename must be a string")
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if columns is not None and not isinstance(columns, list):
        raise TypeError("columns must be a list")
    if selection is not None and not isinstance(selection, (str, list)):
        raise TypeError("selection must be a string or list")
    data = []
    with open(filename, "rb") as f:
        while True:
            event = f.read(16)
            if not event:
                break
            event_name = event.decode("utf-8")
            if event_name == name:
                data.append(np.frombuffer(f.read(16), dtype=np.float64))
    if columns is not None:
        data = [d for d, c in zip(data, columns) if c in columns]
    if selection is not None:
        if isinstance(selection, str):
            selection = [selection]
        for s in selection:
            op = s.split(">")[0]
            val = float(s.split(">")[1])
            data = [d for d in data if d[op] > val]
    return Table(data)

