def fit_transform(
            self, tables=None, transformer_dict=None, transformer_list=None, missing=None):
        """Create, apply and store the specified transformers for the given tables.

        Args:
            tables(dict):   Mapping of table names to `tuple` where each tuple is on the form
                            (`pandas.DataFrame`, `dict`). The `DataFrame` contains the table data
                            and the `dict` the corresponding meta information.
                            If not specified, the tables will be retrieved using the meta_file.

            transformer_dict(dict):     Mapping  `tuple(str, str)` -> `str` where the tuple is
                                        (table_name, column_name).

            transformer_list(list):     List of transformers to use. Overrides the transformers in
                                        the meta_file.

            missing(bool):      Wheter or not use NullTransformer to handle missing values.

        Returns:
            dict: Map from `str` (table_names) to `pandas.DataFrame` (transformed data).
        """
        if tables is None:
            tables = self.get_tables()
        if transformer_dict is None:
            transformer_dict = self.get_transformer_dict()
        if transformer_list is None:
            transformer_list = self.get_transformer_list()
        if missing is None:
            missing = self.get_missing()
        transformed_tables = {}
        for table_name, (table_data, meta) in tables.items():
            transformed_data = table_data.copy()
            for column_name, transformer in transformer_dict.get(table_name, {}).items():
                if column_name in transformed_data.columns:
                    transformed_data[column_name] = transformer.fit_transform(transformed_data[column_name])
            if missing:
                for column_name in transformed_data.columns:
                    if column_name in transformed_data.columns:
                        transformed_data[column_name] = NullTransformer().fit_transform(transformed_data[column_name])
            transformed_tables[table_name] = transformed_data

        return transformed_tables

