def to_timestamp(self, freq=None, how='start'):
        """
        Cast to DatetimeArray/Index.

        Parameters
        ----------
        freq : string or DateOffset, optional
            Target frequency. The default is 'D' for week or longer,
            'S' otherwise
        how : {'s', 'e', 'start', 'end'}

        Returns
        -------
        DatetimeArray/Index
        """
        if freq is None:
            freq = 'D' if self.inferred_freq >= 'W' else 'S'
        if how not in ['s', 'e','start', 'end']:
            raise ValueError("'how' must be either's', 'e','start', or 'end'")
        if how in ['s','start']:
            return self.dt.floor(freq)
        else:
            return self.dt.ceil(freq)

