def vpathto(self, other_version):
        """Return relative path to current document in another version. Like Sphinx's pathto().

        If the current document doesn't exist in the other version its master_doc path is returned instead.

        :raise KeyError: If other_version doesn't exist.

        :param str other_version: Version to link to.

        :return: Relative path.
        :rtype: str
        """
        if other_version not in self.env.versions:
            raise KeyError(f"Version '{other_version}' doesn't exist.")

        current_doc = self.env.doc2path(self.env.docname)
        if current_doc not in self.env.versions[other_version].documents:
            return self.env.versions[other_version].doc2path(self.env.versions[other_version].master_doc)

        return self.env.versions[other_version].doc2path(current_doc)

