    while True:
        ready = select.select([fd], [], [], deadline - time.time())
        if not ready[0]:
            raise mitogen.core.TimeoutError()
        try:
            data = os.read(fd, 4096)
        except OSError as e:
            if e.errno == errno.EAGAIN:
                continue
            elif e.errno == errno.EINTR:
                continue
            elif e.errno == errno.EOF:
