def zero_to_one(table, option):
    """
    normalize from zero to one for row or table
    """
    if option == 'row':
        for i, row in enumerate(table):
            min_val = min(row)
            max_val = max(row)
            for j, val in enumerate(row):
                table[i][j] = (val - min_val) / (max_val - min_val)
    elif option == 'table':
        min_val = min(val for row in table for val in row)
        max_val = max(val for row in table for val in row)
        for i, row in enumerate(table):
            for j, val in enumerate(row):
                table[i][j] = (val - min_val) / (max_val - min_val)
