mgc_code:
def human_duration(time1, time2=None, precision=0, short=False):
    """ Return a human-readable representation of a time delta.

        @param time1: Relative time value.
        @param time2: Time base (C{None} for now; 0 for a duration in C{time1}).
        @param precision: How many time units to return (0 = all).
        @param short: Use abbreviations, and right-justify the result to always the same length.
        @return: Formatted duration.
    """
    if time2 is None:
        time2 = 0
    delta = abs(time1 - time2)
    units = []
    if delta >= 86400:
        days = delta // 86400
        units.append(f"{days}d")
        delta -= days * 86400
    if delta >= 3600:
        hours = delta // 3600
        units.append(f"{hours}h")
        delta -= hours * 3600
    if delta >= 60:
        minutes = delta // 60
        units.append(f"{minutes}m")
        delta -= minutes * 60
    if delta > 0:
        units.append(f"{delta}s")
    if short:
        units = [u.replace("second", "s").replace("minute", "m").replace("hour", "h").replace("day", "d") for u in units]
    result = " ".join(units)
    if precision > 0:
        result = " ".join(units[:precision])
    return result

