def template(basedir, text, vars, lookup_fatal=True, expand_lists=False):
    """ run a text buffer through the templating engine until it no longer changes """
    while True:
        new_text = text
        for var in vars:
            if var in text:
                if lookup_fatal:
                    raise Exception(f"Unknown variable {var}")
                else:
                    new_text = new_text.replace(var, "")
        if new_text == text:
