def iter_descendants(self, strategy="levelorder", is_leaf_fn=None):
        """ Returns an iterator over all descendant nodes."""
        if strategy == "levelorder":
            queue = [self]
            while queue:
                node = queue.pop(0)
                if is_leaf_fn and is_leaf_fn(node):
                    continue
                yield node
                queue.extend(node.children)
        elif strategy == "preorder":
            if is_leaf_fn and is_leaf_fn(self):
                return
            yield self
            for child in self.children:
                yield from child.iter_descendants(strategy, is_leaf_fn)
        elif strategy == "postorder":
            for child in self.children:
                yield from child.iter_descendants(strategy, is_leaf_fn)
            if is_leaf_fn and is_leaf_fn(self):
                return
            yield self
        else:
            raise ValueError("Invalid strategy")

