def start(queue, profile=None, tag='salt/engine/sqs', owner_acct_id=None):
    """
    Listen to sqs and fire message on event bus
    """
    if profile is None:
        profile = 'default'
    if owner_acct_id is None:
        owner_acct_id = '123456789012'
    sqs_client = boto3.client('sqs', profile_name=profile)
    queue_url = sqs_client.get_queue_url(QueueName=queue, OwnerAccountId=owner_acct_id)['QueueUrl']
    while True:
        messages = sqs_client.receive_message(QueueUrl=queue_url, AttributeNames=['All'], MaxNumberOfMessages=10)['Messages']
        for message in messages:
            sqs_client.delete_message(QueueUrl=queue_url, ReceiptHandle=message['ReceiptHandle'])
            event = json.loads(message['Body'])
            salt.utils.event.send(tag, event)

