def condense(self):
        """
        Condense the data set to the distinct intervals based on the pseudo key.
        """
        distinct_intervals = []
        for interval in self.intervals:
            overlapping_intervals = [i for i in distinct_intervals if i.overlaps(interval)]
            if not overlapping_intervals:
                distinct_intervals.append(interval)
            else:
                for i in overlapping_intervals:
                    i.merge(interval)

        self.intervals = distinct_intervals

