def namedb_state_create_sanity_check( opcode, op_data, history_id, preorder_record, record_table ):
    """
    Sanity checks on a preorder and a state-creation operation:
    * the opcode must match the op_data
    * the history_id and operation must match the preorder
    * everything must match the record table.

    Return True on success
    Raise an exception on error.

    DO NOT CALL THIS METHOD DIRECTLY.
    """
    if opcode!= op_data['opcode']:
        raise ValueError("Opcode mismatch")
    if history_id!= preorder_record['history_id']:
        raise ValueError("History ID mismatch")
    if op_data['history_id']!= preorder_record['history_id']:
        raise ValueError("History ID mismatch")
    if op_data['name']!= preorder_record['name']:
        raise ValueError("Name mismatch")
    if op_data['value']!= preorder_record['value']:
        raise ValueError("Value mismatch")
    if op_data['name'] not in record_table:
        raise ValueError("Name not found in record table")
    if record_table[op_data['name']]!= op_data['value']:
        raise ValueError("Record table value mismatch")

    return True

