def sort_cyclic_graph_best_effort(graph, pick_first='head'):
    """Fallback for cases in which the graph has cycles."""
    sorted_nodes = []
    visited = set()

    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        for neighbor in graph[node]:
            dfs(neighbor)
        sorted_nodes.append(node)

    for node in graph:
        dfs(node)

    if pick_first == 'head':
        return sorted_nodes
    else:
        return sorted_nodes[::-1]

