def _upcase_word(text, pos):
    """Uppercase the current (or following) word."""
    start = pos
    while start < len(text) and not text[start].isalpha():
        start += 1
    end = start + 1
    while end < len(text) and text[end].isalpha():
        end += 1
    return text[:start] + text[start:end].upper() + text[end:]

