def _fwhm_side_lineal(uu, vv):
    """Compute r12 using linear interpolation."""
    if len(uu)!= len(vv):
        raise ValueError("Input arrays must have the same length.")
    if len(uu) < 2:
        raise ValueError("Input arrays must have at least two elements.")
    if not all(u < v for u, v in zip(uu, uu[1:])):
        raise ValueError("Input arrays must be sorted in ascending order.")
    if not all(v > 0 for v in vv):
        raise ValueError("Input arrays must contain only positive values.")
    r12 = []
    for u in uu:
        i = next((i for i, v in enumerate(vv) if v >= u), len(vv) - 1)
        r12.append(u + (u - vv[i - 1]) * (vv[i] - vv[i - 1]) / (vv[i] - vv[i - 1]))

    return r12

