def _gatherDataFromLookups(gpos, scriptOrder):
    """
    Gather kerning and classes from the applicable lookups
    and return them in script order.
    """
    kerning = {}
    classes = {}
    for lookup in gpos.lookups:
        if lookup.kerning:
            kerning.update(lookup.kerning)
        if lookup.classes:
            classes.update(lookup.classes)
    sorted_kerning = {script: kerning[script] for script in scriptOrder if script in kerning}
    sorted_classes = {script: classes[script] for script in scriptOrder if script in classes}

    return sorted_kerning, sorted_classes

