def IpaS(d, a, tt_instance=True):
    """A special bidiagonal _matrix in the QTT-format
    M = IPAS(D, A)
    Generates I+a*S_{-1} _matrix in the QTT-format:
    1 0 0 0
    a 1 0 0
    0 a 1 0
    0 0 a 1
    Convenient for Crank-Nicolson and time gradient matrices
    """
    if not isinstance(d, int) or d < 1:
        raise ValueError("d must be a positive integer")
    if not isinstance(a, (int, float)):
        raise ValueError("a must be a number")
    if not isinstance(tt_instance, bool):
        raise ValueError("tt_instance must be a boolean")
    if tt_instance:
        return [1, a] * d
    else:
        return [[1 if i == j else a if abs(i - j) == 1 else 0 for j in range(d)] for i in range(d)]

