def wraps(
    wrapped, assigned=functools.WRAPPER_ASSIGNMENTS, updated=functools.WRAPPER_UPDATES
):
    """Cython-compatible functools.wraps implementation."""
    def decorator(func):
        for attr in assigned:
            try:
                getattr(wrapped, attr)
            except AttributeError:
                pass
            else:
                setattr(func, attr, getattr(wrapped, attr))
        for attr in updated:
            getattr(func, attr).update(getattr(wrapped, attr, {}))
        return func
    return decorator

