def __execute_fromimport_star(module, modname, import_tuples, ignore_list=[],
                              ignore_startswith=[], ignore_endswith=[],
                              check_not_imported=True, verbose=False,
                              veryverbose=False):
    r"""
    Effectively import * statements

    The dynamic_import must happen before any * imports otherwise it wont catch
    anything.

    Ignore:
        ignore_startswith = []
        ignore_endswith = []
        check_not_imported = False
        verbose = True
        veryverbose = True
    """
    if check_not_imported:
        for name in dir(module):
            if name.startswith('_'):
                continue
            if name in ignore_list:
                continue
            if any(name.startswith(prefix) for prefix in ignore_startswith):
                continue
            if any(name.endswith(suffix) for suffix in ignore_endswith):
                continue
            if name in globals():
                continue
            if name in locals():
                continue
            if verbose:
                print('Importing %r from %r' % (name, modname))
            if veryverbose:
                print('Importing %r from %r' % (name, modname))
            globals()[name] = getattr(module, name)

