def syllabify(word):
    """Syllabify the given word, whether simplex or complex."""
    vowels = 'aeiouy'
    syllables = []
    current_syllable = ''

    for letter in word:
        if letter in vowels:
            current_syllable += letter
            syllables.append(current_syllable)
            current_syllable = ''
        else:
            current_syllable += letter

    if current_syllable:
        syllables[-1] += current_syllable

    return syllables

