def parse_template(self, pattern):
        """Parse template."""
        tokens = pattern.split()
        parsed_template = []
        for token in tokens:
            if token.startswith("{{") and token.endswith("}}"):
                parsed_template.append({"type": "variable", "value": token[2:-2]})
            else:
                parsed_template.append({"type": "literal", "value": token})

        return parsed_template

