def makefractalCIJ(mx_lvl, E, sz_cl, seed=None):
    if seed is not None:
        np.random.seed(seed)
    N = 2**mx_lvl
    CIJ = np.zeros((N, N))
    for lvl in range(mx_lvl):
        n_cl = 2**lvl
        cl_sz = N // n_cl
        for i in range(n_cl):
            for j in range(n_cl):
                if i!= j:
                    p = 1 / (E**lvl)
                    if np.random.rand() < p:
                        CIJ[i*cl_sz:(i+1)*cl_sz, j*cl_sz:(j+1)*cl_sz] = 1
    K = np.sum(CIJ)
    return CIJ, int(K)

