def flush(table='filter', chain='', family='ipv4'):
    """
    Flush the chain in the specified table, flush all chains in the specified
    table if not specified chain.

    CLI Example:

    .. code-block:: bash

        salt '*' iptables.flush filter INPUT

        IPv6:
        salt '*' iptables.flush filter INPUT family=ipv6
    """
    if family == 'ipv4':
        command = 'iptables'
    elif family == 'ipv6':
        command = 'ip6tables'
    else:
        raise ValueError(f"Invalid family: {family}")

    if chain:
        command += f" -t {table} -F {chain}"
    else:
        command += f" -t {table} -F"

    return __salt__['cmd.run'](command)

