def clone_git_repo(git_url, target_dir=None, commit=None, retry_times=GIT_MAX_RETRIES, branch=None, depth=None):
    if target_dir and not os.path.exists(target_dir):
        os.makedirs(target_dir)
    cmd = ['git', 'clone', git_url, target_dir]
    if depth:
        cmd.extend(['--depth', str(depth)])
        if not branch:
            raise ValueError("branch is required when depth is provided")
        cmd.extend(['--branch', branch])
    for _ in range(retry_times):
        try:
            subprocess.run(cmd, check=True)
            break
        except subprocess.CalledProcessError as e:
            print(f"Failed to clone git repo: {e}")
    if commit:
        cmd = ['git', 'checkout', commit]
        subprocess.run(cmd, check=True, cwd=target_dir)
    cmd = ['git','rev-parse', 'HEAD']
    result = subprocess.run(cmd, capture_output=True, text=True, cwd=target_dir)
    return target_dir, int(result.returncode), result.stdout.strip()

