def pty_make_controlling_tty(tty_fd):
    """This makes the pseudo-terminal the controlling tty. This should be
    more portable than the pty.fork() function. Specifically, this should
    work on Solaris. """
    import os
    import fcntl
    import termios
    import struct

    def ioctl(fd, request, arg):
        return fcntl.ioctl(fd, request, struct.pack('l', arg))

    def tcgetsid(fd):
        return ioctl(fd, termios.TIOCGSID, 0)

    sid = tcgetsid(tty_fd)
    if sid < 0:
        raise OSError("tcgetsid() failed")
    if os.setsid() < 0:
        raise OSError("setsid() failed")
    if tcgetsid(tty_fd)!= sid:
        raise OSError("Failed to make pseudo-terminal the controlling tty")

