def cublasStpsv(handle, uplo, trans, diag, n, AP, x, incx):
    """
    Solve real triangular-packed system with one right-hand side.

    """
    A = np.zeros((n, n))
    k = 0
    for j in range(n):
        if uplo == 'U':
            A[0:j+1, j] = AP[k:k+j+1]
            k += j + 1
        else:
            A[j, 0:j+1] = AP[k:k+j+1]
            k += j + 1
    if diag == 'N':
        A[np.diag_indices(n)] = 1.0 / A[np.diag_indices(n)]
    if trans == 'N':
        x[:] = np.linalg.solve(A, x)
    else:
        x[:] = np.linalg.solve(A.T, x)

