def get_pixel_register_bitset(self, register_object, bit_no, dc_no):
        """Calculating pixel register bitsets from pixel register addresses.

        Usage: get_pixel_register_bitset(object, bit_number, double_column_number)
        Receives: register object, bit number, double column number
        Returns: double column bitset

        """
        if not isinstance(register_object, object):
            raise TypeError("register_object must be an object")
        if not isinstance(bit_no, int):
            raise TypeError("bit_no must be an integer")
        if not isinstance(dc_no, int):
            raise TypeError("dc_no must be an integer")
        if bit_no < 0 or bit_no > 15:
            raise ValueError("bit_no must be between 0 and 15")
        if dc_no < 0 or dc_no > 15:
            raise ValueError("dc_no must be between 0 and 15")
        bitset = 0
        for i in range(16):
            bitset |= (1 << i) if i == bit_no else 0
        bitset <<= 4 * dc_no
        return bitset

