def _sentinel_parse_scene_id(sceneid):
    pattern = r'^S2(?P<satellite>[AB])_tile_(?P<acquisitionYear>\d{4})(?P<acquisitionMonth>\d{2})(?P<acquisitionDay>\d{2})_(?P<utm>\d{2})(?P<lat>[NS])(?P<sq>[A-Z0-9]{2})_(?P<num>\d+)$'
    match = re.match(pattern, sceneid)
    if match:
        metadata = match.groupdict()
        metadata['scene'] = sceneid
        metadata['key'] = f'tiles/{metadata["utm"]}/{metadata["lat"]}/{metadata["sq"]}/{metadata["acquisitionYear"]}/{metadata["acquisitionMonth"]}/{metadata["acquisitionDay"]}/{metadata["num"]}'
        return metadata
    else:
        raise ValueError('Invalid scene id')

