def generate_reps(min_reps=3, max_reps=8, total=25, existing=None):
    if existing is None:
        existing = []
    total_remaining = total - sum(existing)
    if total_remaining <= 0:
        return []
    max_reps = min(max_reps, total_remaining)
    reps_list = []
    while sum(reps_list) < total_remaining:
        reps = random.randint(min_reps, max_reps)
        reps_list.append(reps)
    return reps_list

