def _recv_internal(self, timeout):
        """
        Read a message from a NI-CAN bus.

        :param float timeout:
            Max time to wait in seconds or None if infinite

        :raises can.interfaces.nican.NicanError:
            If reception fails
        """
        if timeout is not None:
            end_time = time.time() + timeout
        while True:
            if timeout is not None:
                timeout = end_time - time.time()
                if timeout < 0:
                    raise can.interfaces.nican.NicanError("Timeout expired")
            try:
                msg = self._recv_one_message(timeout)
                return msg
            except can.interfaces.nican.NicanError as e:
                if e.error_code == can.interfaces.nican.NicanError.ERROR_TIMEOUT:
                    continue
                else:
                    raise

